udience","options":["Audience","Symbolism","Genre","Novel"],"card_id":null},"after":{"prompt":"Картина","correct_answer":"Painting","options":["Painting","Symbolism","Genre","Novel"],"card_id":"aabbccdd-9999-4004-c003-b20000000000"}},{"table":"lessons","id":"aabbccdd-1111-4005-0005-b20000000000","before":{"title":"Idiomatic Equivalents","description":"Idiomatic Equivalents"},"after":{"title":"Phrasal Verbs","description":"Phrasal Verbs"}},{"table":"lessons","id":"aabbccdd-2222-4005-0005-b20000000000","before":{"title":"Idiomatic Equivalents","description":"Idiomatic Equivalents"},"after":{"title":"Phrasal Verbs","description":"Phrasal Verbs"}},{"table":"lessons","id":"aabbccdd-3333-4005-0005-b20000000000","before":{"title":"Idiomatic Equivalents","description":"Idiomatic Equivalents"},"after":{"title":"Phrasal Verbs","description":"Phrasal Verbs"}},{"table":"lessons","id":"aabbccdd-4444-4005-0005-b20000000000","before":{"title":"Idiomatic Equivalents","description":"Idiomatic Equivalents"},"after":{"title":"Phrasal Verbs","description":"Phrasal Verbs"}},{"table":"lessons","id":"aabbccdd-5555-4005-0005-b20000000000","before":{"title":"Idiomatic Equivalents","description":"Idiomatic Equivalents"},"after":{"title":"Phrasal Verbs","description":"Phrasal Verbs"}},{"table":"lessons","id":"aabbccdd-6666-4005-0005-b20000000000","before":{"title":"Idiomatic Equivalents","description":"Idiomatic Equivalents"},"after":{"title":"Phrasal Verbs","description":"Phrasal Verbs"}},{"table":"lessons","id":"aabbccdd-7777-4005-0005-b20000000000","before":{"title":"Idiomatic Equivalents","description":"Idiomatic Equivalents"},"after":{"title":"Phrasal Verbs","description":"Phrasal Verbs"}},{"table":"lessons","id":"aabbccdd-8888-4005-0005-b20000000000","before":{"title":"Idiomatic Equivalents","description":"Idiomatic Equivalents"},"after":{"title":"Phrasal Verbs","description":"Phrasal Verbs"}},{"table":"lessons","id":"aabbccdd-9999-4005-0005-b20000000000","before":{"title":"Idiomatic Equivalents","description":"Idiomatic Equivalents"},"after":{"title":"Phrasal Verbs","description":"Phrasal Verbs"}}]}$question_audit_payload$::jsonb;
  patch jsonb; guard jsonb; current_row jsonb; assignments text; changed integer;
BEGIN
  FOR guard IN SELECT value FROM jsonb_array_elements(plan->'context_guards') LOOP
    IF guard->>'table' <> 'units' THEN RAISE EXCEPTION 'Out-of-scope question audit context'; END IF;
    EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE id = $1::uuid FOR SHARE', guard->>'table') INTO current_row USING guard->>'id';
    IF current_row IS NULL OR EXISTS (SELECT 1 FROM jsonb_each(guard->'before') field WHERE current_row->field.key IS DISTINCT FROM field.value) THEN
      RAISE EXCEPTION 'Audited category changed; review before reverting: %/%', guard->>'table', guard->>'id';
    END IF;
  END LOOP;
  FOR patch IN SELECT value FROM jsonb_array_elements(plan->'patches') LOOP
    IF NOT (patch->>'table' = ANY(ARRAY['courses','units','lessons','exercises','cards','grammar_rules','writing_prompts','reading_passages','reading_questions','checkpoint_items'])) THEN
      RAISE EXCEPTION 'Out-of-scope question audit table';
    END IF;
    EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE id = $1::uuid FOR UPDATE', patch->>'table') INTO current_row USING patch->>'id';
    IF current_row IS NULL THEN RAISE EXCEPTION 'Missing audited row %/%', patch->>'table', patch->>'id'; END IF;
    IF NOT EXISTS (SELECT 1 FROM jsonb_each(patch->'after') field WHERE current_row->field.key IS DISTINCT FROM field.value) THEN CONTINUE; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_each(patch->'before') field WHERE current_row->field.key IS DISTINCT FROM field.value) THEN RAISE EXCEPTION 'Audited row changed; review before reverting: %/%', patch->>'table', patch->>'id'; END IF;
    SELECT string_agg(format('%I = (jsonb_populate_record(NULL::public.%I, $1)).%I', key, patch->>'table', key), ', ' ORDER BY key) INTO assignments FROM jsonb_object_keys(patch->'after') key;
    EXECUTE format('UPDATE public.%I SET %s WHERE id = $2::uuid', patch->>'table', assignments) USING patch->'after', patch->>'id';
    GET DIAGNOSTICS changed = ROW_COUNT;
    IF changed <> 1 THEN RAISE EXCEPTION 'Unexpected affected-row count: %', changed; END IF;
  END LOOP;
END
$question_audit$;
